// Modules/Networking/Package.swift
import PackageDescription

let package = Package(
  name: "Networking",
  platforms: [.iOS(.v17)],
  products: [
    // The only way out of the package. Delete this line and no consumer can
    // import Networking, however public the types inside it are.
    .library(name: "Networking", targets: ["Networking"]),
    // HTTPCore is deliberately absent: an implementation detail nobody may import.
  ],
  targets: [
    .target(name: "Networking", dependencies: ["HTTPCore"]),  // same package: bare target name
    .target(name: "HTTPCore"),
    .testTarget(name: "NetworkingTests", dependencies: ["Networking"]),
  ]
)

// Modules/Profile/Package.swift — the consumer
let profilePackage = Package(
  name: "Profile",
  products: [.library(name: "Profile", targets: ["Profile"])],
  dependencies: [.package(path: "../Networking")],
  targets: [
    .target(name: "Profile", dependencies: [
      // `package:` is the package IDENTITY (folder or repo name), not the library name
      .product(name: "Networking", package: "Networking"),
    ]),
  ]
)

// Sources/HTTPCore/RetryPolicy.swift
public struct Endpoint { public init() {} }  // crosses the module boundary
package struct RetryPolicy {}                // Networking may use it, Profile cannot see it
struct SocketPool {}                         // internal: the default, and the right default

// App/Package.swift — the same requirements Xcode's package UI writes for you
import PackageDescription

let package = Package(
  name: "App",
  dependencies: [
    // from: == .upToNextMajor -> [1.2.0, 2.0.0). Any 1.x the maintainer tags can
    // arrive at the next resolve, on someone else's machine, on a Friday.
    .package(url: "https://github.com/apple/swift-log.git", from: "1.2.0"),

    // Tighter: only patch releases move on their own.
    .package(url: "https://github.com/vendor/analytics.git", .upToNextMinor(from: "4.3.0")),

    // Deliberate pin for anything that runs code at build time (macros, plugins).
    .package(url: "https://github.com/vendor/codegen.git", exact: "0.9.1"),

    // Never in a shipping app: unversioned, unreproducible, and a package that
    // depends on a branch cannot itself be depended on by anyone else.
    // .package(url: "https://github.com/vendor/sdk.git", branch: "main"),
  ],
  targets: [.target(name: "App")]
)

// Committed, and the only reason two machines agree:
//   App.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved
//
// CI honours the pins and never rewrites them:
//   xcodebuild -resolvePackageDependencies -clonedSourcePackagesDirPath .spm
//   git diff --exit-code -- '**/Package.resolved'   # fail the job on drift
//
// Updating is its own pull request, one dependency at a time:
//   swift package update swift-log

// Modules/DesignSystem/Package.swift
import PackageDescription

let package = Package(
  name: "DesignSystem",
  platforms: [.iOS(.v17)],
  products: [
    // No explicit type == automatic: Xcode links this statically.
    // Nothing for dyld to load, nothing to embed, nothing to sign.
    .library(name: "DesignSystem", targets: ["DesignSystem"]),

    // Explicitly dynamic: one image in Frameworks/, one dyld load, one shared copy.
    // Worth it only when an extension or another framework must share this code.
    // .library(name: "DesignSystem", type: .dynamic, targets: ["DesignSystem"]),
  ],
  targets: [.target(name: "DesignSystem")]
)

// What each embedded dynamic image charges you before main() runs:
//   path search -> mmap -> rebase/bind fixups -> ObjC class and category
//   registration -> +load and global initialisers.
// Statically linked code skips every step: it is already in the executable.

// Xcode framework targets get the third option, from Xcode 15:
//   on the framework:  MERGEABLE_LIBRARY = YES         // passes -make_mergeable
//   on the app target: MERGED_BINARY_TYPE = automatic  // Release merges, Debug does not

// A global is per copy of the code, not per app — two links, two instances:
public enum Theme {
  public static let shared = Theme()   // one per image that statically linked this module
}

// WRONG: Analytics is static (no explicit type), and two dynamic frameworks each
// link it. Both images end up containing AnalyticsTracker and its globals.
let wrong = Package(
  name: "App",
  products: [
    .library(name: "Analytics", targets: ["Analytics"]),
    .library(name: "Feed", type: .dynamic, targets: ["Feed"]),
    .library(name: "Profile", type: .dynamic, targets: ["Profile"]),
  ],
  targets: [
    .target(name: "Analytics"),
    .target(name: "Feed", dependencies: ["Analytics"]),
    .target(name: "Profile", dependencies: ["Analytics"]),
  ]
)

// RIGHT: one image owns the code, the others link against it.
let right = Package(
  name: "App",
  products: [
    .library(name: "Analytics", type: .dynamic, targets: ["Analytics"]),
    .library(name: "Feed", type: .dynamic, targets: ["Feed"]),
    .library(name: "Profile", type: .dynamic, targets: ["Profile"]),
  ],
  targets: [
    .target(name: "Analytics"),
    .target(name: "Feed", dependencies: ["Analytics"]),
    .target(name: "Profile", dependencies: ["Analytics"]),
  ]
)

// Proving it on the built app, before and after:
//   otool -L MyApp.app/MyApp
//   nm -gU MyApp.app/Frameworks/Feed.framework/Feed    | grep AnalyticsTracker
//   nm -gU MyApp.app/Frameworks/Profile.framework/Profile | grep AnalyticsTracker

// The silent Swift half of the same bug — one instance per copy of the code,
// so Feed's events and Profile's events queue up in two different places.
public final class AnalyticsTracker {
  public static let shared = AnalyticsTracker()
}

// Debug.xcconfig — compile fast
// SWIFT_COMPILATION_MODE  = singlefile
// SWIFT_OPTIMIZATION_LEVEL = -Onone
//
// Release.xcconfig — run fast
// SWIFT_COMPILATION_MODE  = wholemodule
// SWIFT_OPTIMIZATION_LEVEL = -O
//
// Temporarily, in either config, to find the slow code:
// OTHER_SWIFT_FLAGS = $(inherited) -Xfrontend -warn-long-expression-type-checking=300

// Slow: the solver weighs every + overload and every literal type in one go
let summarySlow = "Cart: " + String(items.count) + " items, "
    + String(format: "%.2f", subtotal + shipping - discount) + " " + currency.code

// Fast: an annotated intermediate plus interpolation collapses the search space
let total: Double = subtotal + shipping - discount
let summaryFast = "Cart: \(items.count) items, "
    + "\(total.formatted(.number.precision(.fractionLength(2)))) \(currency.code)"

// Same trap in a heterogeneous literal — annotate the type and the warning goes away
let row: [String: Any] = ["id": id, "count": items.count, "total": total]

// And in SwiftUI: compute the branch above body instead of nesting ternaries in it
var body: some View {
  let tint: Color = isHighlighted ? .accentColor : .secondary
  return Text(title)
    .font(isHighlighted ? .headline : .body)
    .foregroundStyle(tint)
}

// Package.swift — one product, two targets that share internals
import PackageDescription

let package = Package(
  name: "Checkout",
  products: [.library(name: "Checkout", targets: ["Checkout"])],
  targets: [
    .target(name: "CheckoutCore"),                        // package-internal
    .target(name: "Checkout", dependencies: ["CheckoutCore"]),
  ]
)

// Sources/CheckoutCore/PriceEngine.swift
// Visible to the Checkout target, invisible to the app that imports Checkout
package struct PriceEngine {
  package init() {}
  package func total(of lines: [Line]) -> Decimal {
    lines.reduce(Decimal.zero) { $0 + $1.amount }
  }
}

// Sources/Checkout/CheckoutScreen.swift — the module's entire API surface
public struct CheckoutScreen: View {
  private let model: CheckoutModel
  public init(order: OrderID, payments: any PaymentGateway) {   // public init is required
    self.model = CheckoutModel(order: order, payments: payments)
  }
  public var body: some View { Text("Checkout") }
}

public protocol PaymentGateway: Sendable {                       // what the app must supply
  func authorize(_ amount: Decimal) async throws -> Receipt
}

// Trap: this makes `import Checkout` silently mean `import Networking` too,
// so every client depends on a module it never named.
@_exported import Networking

// Package.swift — the interface target is what breaks the cycle
import PackageDescription

let package = Package(
  name: "Features",
  products: [
    .library(name: "Checkout", targets: ["Checkout"]),
    .library(name: "Profile", targets: ["Profile"]),
  ],
  targets: [
    .target(name: "ProfileInterface"),                              // depends on nothing
    .target(name: "CheckoutInterface"),
    .target(name: "Profile", dependencies: ["ProfileInterface", "CheckoutInterface"]),
    .target(name: "Checkout", dependencies: ["CheckoutInterface", "ProfileInterface"]),
  ]
)

// Sources/ProfileInterface — protocols and plain values only
public struct Address: Sendable, Identifiable { public let id: UUID }

@MainActor public protocol AddressEditing {
  func editAddress(current: Address?) async -> Address?
}

// Sources/Profile — the implementation nobody else imports
@MainActor public struct AddressEditor: AddressEditing {
  public init() {}
  public func editAddress(current: Address?) async -> Address? { current }
}

// Sources/Checkout — asks for the capability, not for the module
@MainActor public final class CheckoutModel {
  private let addresses: any AddressEditing
  public init(addresses: any AddressEditing) { self.addresses = addresses }
}

// App target — the only place that knows both halves exist
let checkout = CheckoutModel(addresses: AddressEditor())

// Framework target built with BUILD_LIBRARY_FOR_DISTRIBUTION = YES

// Not frozen: you may add a case in 2.0, so clients must handle the unknown one
public enum PaymentState: Sendable {
  case pending
  case settled(Receipt)
  case failed(String)
}

// Frozen: clients may switch exhaustively and read fields at a fixed offset —
// and you can never add a case or a stored property to it again
@frozen public struct Money: Sendable {
  public let amount: Decimal
  public let currency: String

  @inlinable public init(amount: Decimal, currency: String) {
    // This body is copied into every client, so old apps keep running the old
    // version of it even after you ship a fix. Keep inlinable bodies trivial.
    self.amount = amount
    self.currency = currency
  }
}

// In a client module, compiled against the generated .swiftinterface
func describe(_ state: PaymentState) -> String {
  switch state {
  case .pending: "waiting"
  case .settled(let receipt): "paid \(receipt.id)"
  case .failed(let reason): "failed: \(reason)"
  @unknown default: "unsupported state — update the SDK"   // required, enum is resilient
  }
}

// Breaking changes once 1.0 is in someone's app:
//   removing `public`, renaming a symbol, reordering enum cases of a @frozen enum,
//   or dropping @frozen / @inlinable from something that shipped with it.

// Package.swift
import PackageDescription

let package = Package(
  name: "Crypto",
  products: [.library(name: "Crypto", targets: ["Crypto"])],
  targets: [
    // C sources you own: headers in Sources/CSodiumShim/include/, modulemap generated
    .target(
      name: "CSodiumShim",
      cSettings: [.headerSearchPath("private")],
      linkerSettings: [.linkedLibrary("sodium")]
    ),
    .target(name: "Crypto", dependencies: ["CSodiumShim"]),
  ]
)

// Sources/CSodiumShim/module.modulemap — only needed for a .systemLibrary target
//
//   module CSodium [system] {
//     header "shim.h"
//     link "sodium"
//     export *
//   }

// Sources/Crypto/Hasher.swift — the single file that touches C
import CSodiumShim
import Foundation

public enum Hasher {
  public static func hash(_ data: Data) -> Data {
    var out = Data(count: 32)
    out.withUnsafeMutableBytes { dst in
      data.withUnsafeBytes { src in
        // Pointers never escape this closure — that is the point of the wrapper
        shim_hash(dst.baseAddress, src.baseAddress, src.count)
      }
    }
    return out
  }
}

import ProjectDescription

// Project.swift — the target graph as reviewable source, no pbxproj in git
let project = Project(
  name: "App",
  settings: .settings(configurations: [
    .debug(name: "Debug", xcconfig: "Config/Debug.xcconfig"),      // step 1 moved these
    .release(name: "Release", xcconfig: "Config/Release.xcconfig"),
  ]),
  targets: [
    .target(
      name: "App",
      destinations: .iOS,
      product: .app,                       // SwiftPM cannot express this product
      bundleId: "com.example.app",
      infoPlist: .file(path: "App/Info.plist"),
      sources: ["App/Sources/**"],
      resources: ["App/Resources/**"],
      dependencies: [
        .external(name: "Checkout"),       // declared in Tuist/Package.swift
        .external(name: "Profile"),
      ]
    ),
    .target(
      name: "AppUITests",
      destinations: .iOS,
      product: .uiTests,
      bundleId: "com.example.app.uitests",
      sources: ["App/UITests/**"],
      dependencies: [.target(name: "App")]
    ),
  ]
)

